pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1 ether * 1000000);
        amount = bound(amount, 1, 1 ether);

        address owner = c.owner();
        vm.deal(address(this), amount);
        c.deposit{value: amount}();

        uint256 preBalance = address(c).balance;
        assertGt(preBalance, 0);
        uint256 ownerBefore = owner.balance;

        vm.prank(owner);
        c.withdrawAll();

        uint256 ownerAfter = owner.balance;
        // General rule: withdrawAll transfers the entire contract balance to the caller (owner).
        assertTrue(ownerAfter - ownerBefore == preBalance);
    }

    receive() external payable {}
}

