pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address funder, uint256 amount, address caller) public {
        // owner is the test contract (deployer in setUp); caller must differ from it
        vm.assume(caller != address(this));
        vm.assume(funder != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract through its payable receive() so a drain is observable
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool paid, ) = address(c).call{value: amount}("");
        assertTrue(paid);
        require(address(c).balance == amount);

        // a NON-OWNER's withdrawAll must revert in the reference contract
        vm.prank(caller);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

