pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(this)); // owner is the deployer (this test contract)
        vm.assume(caller != address(0));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract so draining it is observable
        vm.deal(address(c), amount);

        // a non-owner attempts to withdraw the whole balance
        vm.prank(caller);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Rule: a non-owner cannot drain c; its balance must be intact afterwards.
        // Mutant: withdrawAll succeeds for the non-owner and zeroes address(c).balance.
        assertTrue(address(c).balance == amount, "non-owner drained the contract");
    }
}

