pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, address(c).balance == 0 ? 0 : address(c).balance);
        vm.deal(address(c), 10 ether);
        amount = bound(amount, 0, address(c).balance);

        uint256 balBefore = address(c).balance;
        address owner = c.owner();

        vm.prank(actor);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        uint256 balAfter = address(c).balance;

        // General rule: a withdrawal succeeds only for the owner, and a successful
        // withdrawal moves exactly `amount` out of the contract (to the caller);
        // a failed withdrawal must leave the contract's balance untouched.
        assertTrue(
            (ok && actor == owner && balBefore - balAfter == amount) ||
            (!ok && actor != owner && balAfter == balBefore)
        );
    }
}

